SELECT CASE WHEN p.entry_reason LIKE '%BALANCED_NEUTRAL_5M_WATCH_1H%' THEN 'FIX11G' WHEN p.entry_reason LIKE '%BALANCED_NEUTRAL_5M:%' THEN 'FIX112B' ELSE 'OTHER' END AS auth_path, s.market_regime, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 6) AS gross_pnl FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY auth_path, s.market_regime ORDER BY auth_path, s.market_regime LIMIT 60